      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that this is an update or replication of a previous systematic review, nor does it mention the existence of similar systematic reviews that necessitate this specific one."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of 'models for malaria control optimization', not a review of the effects of a specific intervention itself."
    },
